import { LogicWrapper, MakeLogicType, actions, connect, kea, key, listeners, path, props } from 'kea'
import { router } from 'kea-router'

import { newDashboardLogic } from 'scenes/dashboard/newDashboardLogic'
import { urls } from 'scenes/urls'

import { projectTreeDataLogic } from '~/layout/panel-layout/ProjectTree/projectTreeDataLogic'

export interface ReportsLogicProps {
    folder: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportsLogicValues {
    dashboardCreationLoading: boolean // newDashboardLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportsLogicActions {
    addDashboard: (form: Partial<import('scenes/dashboard/newDashboardLogic').NewDashboardForm>) => {
        form: Partial<import('scenes/dashboard/newDashboardLogic').NewDashboardForm>
    } // newDashboardLogic
    setAsHomeTabDashboardAfterCreation: (
        setAsHomeTabDashboard: boolean,
        openAI?: boolean | undefined
    ) => {
        openAI: boolean
        setAsHomeTabDashboard: boolean
    } // newDashboardLogic
    setRedirectAfterCreation: (redirect: boolean) => {
        redirect: boolean
    } // newDashboardLogic
    setLastNewFolder: (folder: string | null) => {
        folder: string | null
    } // projectTreeDataLogic
    createDashboard: () => {
        value: true
    }
    createInsight: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportsLogicMeta {
    key: any
}

export type reportsLogicType = MakeLogicType<
    reportsLogicValues,
    reportsLogicActions,
    ReportsLogicProps,
    reportsLogicMeta
>

export const reportsLogic: LogicWrapper<reportsLogicType> = kea<reportsLogicType>([
    props({} as ReportsLogicProps),
    key(({ folder }) => folder),
    path((key) => ['products', 'dashboards', 'frontend', 'reportsLogic', key]),
    connect({
        values: [newDashboardLogic, ['isLoading as dashboardCreationLoading']],
        actions: [
            newDashboardLogic,
            ['addDashboard', 'setAsHomeTabDashboardAfterCreation', 'setRedirectAfterCreation'],
            projectTreeDataLogic,
            ['setLastNewFolder'],
        ],
    }),
    actions({ createDashboard: true, createInsight: true }),
    listeners(({ actions, values, props }) => ({
        createDashboard: () => {
            if (values.dashboardCreationLoading) {
                return
            }
            actions.setAsHomeTabDashboardAfterCreation(false)
            actions.setRedirectAfterCreation(true)
            actions.addDashboard({ name: 'New dashboard', _create_in_folder: props.folder, show: true })
        },
        createInsight: () => {
            actions.setLastNewFolder(props.folder)
            router.actions.push(urls.insightNew())
        },
    })),
])
